def components_color(g,color,conn=4):
    n,m=len(g),len(g[0]); seen=set(); comps=[]
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    if conn==8: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
    for r in range(n):
      for c in range(m):
       if g[r][c]!=color or (r,c) in seen: continue
       q=[(r,c)]; seen.add((r,c)); comp=[]
       while q:
        p=q.pop();comp.append(p)
        for dr,dc in dirs:
         x,y=p[0]+dr,p[1]+dc
         if 0<=x<n and 0<=y<m and g[x][y]==color and (x,y) not in seen:
          seen.add((x,y));q.append((x,y))
       comps.append(comp)
    return comps
